CREATE POLICY "deletion_log_worker_system_delete" ON "deletion_log" AS PERMISSIVE FOR DELETE TO "app_worker" USING ((nullif(current_setting('app.scope', true), '') = 'system' and "deletion_log"."completed_at" < ((nullif(current_setting('app.now', true), '')::timestamptz at time zone 'UTC') - interval '24 months') at time zone 'UTC'));--> statement-breakpoint
CREATE POLICY "read_cache_worker_system_delete" ON "read_cache" AS PERMISSIVE FOR DELETE TO "app_worker" USING ((nullif(current_setting('app.scope', true), '') = 'system' and "read_cache"."expires_at" <= nullif(current_setting('app.now', true), '')::timestamptz));